object Solution {
    def evaluate(s: String, knowledge: List[List[String]]): String = {
        val map = knowledge.map { case List(k, v) => k -> v }.toMap
        val sb = new StringBuilder
        var i = 0
        while (i < s.length) {
            if (s(i) == '(') {
                val start = i + 1
                val end = s.indexOf(')', start)
                val key = s.substring(start, end)
                sb.append(map.getOrElse(key, "?"))
                i = end + 1
            } else {
                sb.append(s(i))
                i += 1
            }
        }
        sb.toString()
    }
}

